def page(title, body, css=""):
    return (f'<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">'
            f'<meta name="viewport" content="width=device-width, initial-scale=1">'
            f'<title>{html.escape(title)}</title><style>{BASE_CSS}{css}</style></head>'
            f'<body>{body}</body></html>')

def parse_post(handler):
    n = int(handler.headers.get("Content-Length", 0) or 0)
    raw = handler.rfile.read(n).decode("utf-8") if n else ""
    return urllib.parse.parse_qs(raw)


class Base(BaseHTTPRequestHandler):
    def html(self, text, code=200, cookie=None):
        data = text.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(data)))
        if cookie:
            self.send_header("Set-Cookie", cookie)
        self.end_headers()
        self.wfile.write(data)

    def redirect(self, loc, cookie=None):
        self.send_response(303)
        self.send_header("Location", loc)
        if cookie:
            self.send_header("Set-Cookie", cookie)
        self.end_headers()

    def cookies(self):
        return http.cookies.SimpleCookie(self.headers.get("Cookie", ""))

    def log_message(self, *a):
        return


