def prem_db():
    db = sqlite3.connect(":memory:")
    db.execute("CREATE TABLE members(username TEXT, email TEXT, password TEXT, member_since TEXT)")
    db.executemany("INSERT INTO members VALUES(?,?,?,?)", MEMBERS_SEED)
    db.commit()
    return db

def try_login(u, p):
    # >>> THE BUG <<<  username + password glued straight into the SQL.
    q = ("SELECT username, member_since FROM members "
         "WHERE username = '" + u + "' AND password = '" + p + "'")
    db = prem_db()
    try:
        row = db.execute(q).fetchone(); err = None
    except sqlite3.Error as e:
        row, err = None, str(e)
    db.close()
    return q, row, err

def all_members():
    db = prem_db()
    rows = db.execute("SELECT username, email, password, member_since FROM members").fetchall()
    db.close()
    return rows

def member_by_username(u):
    db = prem_db()
    try:
        row = db.execute("SELECT username, member_since FROM members WHERE username=?", (u,)).fetchone()
    finally:
        db.close()
    return row

