def _loot_table(rows):
    head = ("<tr><th>username</th><th>email</th><th>password</th><th>member since</th></tr>")
    b = ""
    for u, e, pw, since in rows:
        b += (f"<tr><td>{html.escape(u)}</td><td>{html.escape(e)}</td>"
              f"<td style='color:#ff6b6b;font-weight:700;'>{html.escape(pw)}</td>"
              f"<td>{html.escape(since)}</td></tr>")
    return f"<table>{head}{b}</table>"

