class Router(Base):
    def _user(self):
        c = self.cookies()
        if "prem" in c and c["prem"].value.startswith("in:"):
            return c["prem"].value[3:]
        return None

    def do_GET(self):
        path = urllib.parse.urlparse(self.path).path
        if path in ("/", ""):
            self.html(index())
        elif path == "/hack.js":                      # served at root so <script src="/hack.js"> works
            data = HACK_JS.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/javascript; charset=utf-8")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        elif path in ("/blog", "/blog/"):
            self.html(guestbook())
        elif path == "/blog/reset":
            XSS["comments"] = list(XSS_SEED)
            self.redirect("/blog")
        elif path in ("/club", "/club/"):
            u = self._user()
            row = member_by_username(u) if u else None
            self.html(prem_dashboard(row) if row else prem_login())
        elif path == "/club/reset":
            self.redirect("/club", cookie="prem=; Path=/; Max-Age=0")
        else:
            self.html(page("404", '<div class="wrap"><h1>404</h1><p><a href="/">home</a></p></div>'), 404)

    def do_POST(self):
        path = urllib.parse.urlparse(self.path).path
        form = parse_post(self)
        if path == "/blog/comment":
            c = form.get("comment", [""])[0]
            if c.strip():
                XSS["comments"].append(c)             # stored RAW -> the XSS vulnerability
            self.redirect("/blog")
        elif path == "/club":
            u = form.get("username", [""])[0]
            p = form.get("password", [""])[0]
            q, row, err = try_login(u, p)             # user input glued into SQL -> the vulnerability
            if row:
                self.html(prem_dashboard(row), cookie=f"prem=in:{row[0]}; Path=/")
            else:
                self.html(prem_login(denied=True), 401)
        else:
            self.html(page("404", '<div class="wrap"><h1>404</h1></div>'), 404)


